<script lang="ts" module>import type{RxColor}from'$lib/registry/lib/color';export interface ConfirmPopupProps{open?:boolean;title?:string;message:string;confirmLabel?:string;cancelLabel?:string;destructive?:boolean;color?:RxColor;onConfirm?:()=>void;onCancel?:()=>void;onOpenChange?:(open:boolean)=>void}</script>
